uint32_t gameTime = 0;
uint32_t lastSecond = 0;

int main()
{
    initClock();
    initSysTick();
    setupIO();
    randomize();

    uint16_t x = 64;
    uint16_t y = 120;
    uint16_t car1_x = 70;
    int car1_y = -40;

	gameTime = 0; 
	lastSecond = milliseconds;       // sync to current time

    // ── START SCREEN ──────────────────────────────────────────────
    fillRectangle(0, 0, 128, 170, 0x0000);
    printText("TRAFFIC RACER", 5, 60, RGBToWord(255, 80, 0), 0x0000);
    printText("Press -> to start", 2, 120, 0xFFFF, 0x0000);

    while (GPIOB->IDR & (1 << 4)); // wait for PB4 press
    fillRectangle(0, 0, 128, 170, 0x0000);

	char cars[7] = { };
	int current = 0;

    // ── GAME LOOP ─────────────────────────────────────────────────
    while (1)
    {
        fillRectangle(car1_x, car1_y, 50, 36, 0x0000);  // erase enemy
        fillRectangle(x, y, 50, 36, 0x0000);             // erase player

        // move enemy car down
        car1_y += 5;
        if (car1_y > 170)
        {
            car1_y = -36;
            car1_x = (prbs() % 2) ? 20 : 70; // random lane

			current++;
			if (current >= 7) {
        	current = 0; 
    		}		
        }

        // player input
        if (!(GPIOB->IDR & (1 << 4)) && x < 90) x += 5; // right
        if (!(GPIOB->IDR & (1 << 5)) && x > 10) x -= 5; // left

        // draw both cars
        putImage(car1_x, car1_y, 50, 36, cars[current],    0, 0);
        putImage(x,      y,      50, 36, usercar, 0, 0);

        loop(); // update timer

		// collision
		if (x < car1_x + 25 && x + 25 > car1_x &&
   			 y < car1_y + 50 && y + 50 > car1_y)
		{
    		fillRectangle(0, 0, 128, 170, 0x0000);
    		printTextX2("GAME OVER", 5, 60, 0xFFFF, 0x0000);
    		printText("Press -> to restart", 2, 120, 0xFFFF, 0x0000);

    		while (GPIOB->IDR & (1 << 4));  // wait for press
    		while (!(GPIOB->IDR & (1 << 4))); // wait for release

    		// reset
    		x = 64; y = 120;
    		car1_x = 70; car1_y = -40;
    		gameTime = 0;
    		lastSecond = milliseconds;
    		fillRectangle(0, 0, 128, 170, 0x0000);
}

        delay(20);
    }
    return 0;
}

void loop()
{
    if (milliseconds - lastSecond >= 1000)
	{
        lastSecond = milliseconds;
        gameTime++;
        char buffer[16];
        sprintf(buffer, "Time: %lus", gameTime);
        printText(buffer, 0, 0, 0xFFFF, 0x0000);
    }
}

void initSysTick(void)
{
	SysTick->LOAD = 48000;
	SysTick->CTRL = 7;
	SysTick->VAL = 10;
	__asm(" cpsie i "); // enable interrupts
}
void SysTick_Handler(void)
{
	milliseconds++;
}
void initClock(void)
{
	// This is potentially a dangerous function as it could
	// result in a system with an invalid clock signal - result: a stuck system
	// Set the PLL up
	// First ensure PLL is disabled
	RCC->CR &= ~(1u << 24);
	while ((RCC->CR & (1 << 25)))
		; // wait for PLL ready to be cleared

	// Warning here: if system clock is greater than 24MHz then wait-state(s) need to be
	// inserted into Flash memory interface

	FLASH->ACR |= (1 << 0);
	FLASH->ACR &= ~((1u << 2) | (1u << 1));
	// Turn on FLASH prefetch buffer
	FLASH->ACR |= (1 << 4);
	// set PLL multiplier to 12 (yielding 48MHz)
	RCC->CFGR &= ~((1u << 21) | (1u << 20) | (1u << 19) | (1u << 18));
	RCC->CFGR |= ((1 << 21) | (1 << 19));

	// Need to limit ADC clock to below 14MHz so will change ADC prescaler to 4
	RCC->CFGR |= (1 << 14);

	// and turn the PLL back on again
	RCC->CR |= (1 << 24);
	// set PLL as system clock source
	RCC->CFGR |= (1 << 1);
}
void delay(volatile uint32_t dly)
{
	uint32_t end_time = dly + milliseconds;
	while (milliseconds != end_time)
		__asm(" wfi "); // sleep
}

void enablePullUp(GPIO_TypeDef *Port, uint32_t BitNumber)
{
	Port->PUPDR = Port->PUPDR & ~(3u << BitNumber * 2); // clear pull-up resistor bits
	Port->PUPDR = Port->PUPDR | (1u << BitNumber * 2);	// set pull-up bit
}
void pinMode(GPIO_TypeDef *Port, uint32_t BitNumber, uint32_t Mode)
{
	/*
	 */
	uint32_t mode_value = Port->MODER;
	Mode = Mode << (2 * BitNumber);
	mode_value = mode_value & ~(3u << (BitNumber * 2));
	mode_value = mode_value | Mode;
	Port->MODER = mode_value;
}
int isInside(uint16_t x1, uint16_t y1, uint16_t w, uint16_t h, uint16_t px, uint16_t py)
{
	// checks to see if point px,py is within the rectange defined by x,y,w,h
	uint16_t x2, y2;
	x2 = x1 + w;
	y2 = y1 + h;
	int rvalue = 0;
	if ((px >= x1) && (px <= x2))
	{
		// ok, x constraint met
		if ((py >= y1) && (py <= y2))
			rvalue = 1;
	}
	return rvalue;
}

void setupIO()
{
	RCC->AHBENR |= (1 << 18) + (1 << 17); // enable Ports A and B
	display_begin();
	pinMode(GPIOB, 4, 0);
	pinMode(GPIOB, 5, 0);
	pinMode(GPIOA, 8, 0);
	pinMode(GPIOA, 11, 0);
	enablePullUp(GPIOB, 4);
	enablePullUp(GPIOB, 5);
	enablePullUp(GPIOA, 11);
	enablePullUp(GPIOA, 8);
}
